<script setup lang="ts">
import type { MapLayer, GeoShape } from '~/types/community'
import { errorMessage } from '~/utils/format'
const props=defineProps<{layer:MapLayer}>(),emit=defineEmits<{updated:[]}>()
const bounds=useState('map-cache-bounds',()=>({west:88.88,south:29.26,east:88.91,north:29.29,zoom:16}))
const min=ref(Math.max(props.layer.minZoom,Math.min(bounds.value.zoom,props.layer.maxZoom))),max=ref(Math.max(props.layer.minZoom,Math.min(bounds.value.zoom,props.layer.maxZoom))),replace=ref(true),error=ref(''),busy=ref(false),shape=ref<GeoShape|null>(null)
interface Job{id:string;state:string;total:number;processed:number;downloaded:number;failed:number;error:string}
const job=useState<Job|null>(`tile-update-${props.layer.id}`,()=>null)
const running=computed(()=>job.value?.state==='running')
let timer:ReturnType<typeof setTimeout>|undefined
watch(shape,value=>{if(!value)return;const xy=value.type==='MultiPolygon'?value.areas!.flat():value.coordinates;if(value.type==='Point'){error.value='请选择画区域，圈出需要更新的范围';return}bounds.value={west:Math.min(...xy.map(x=>x[0]!)),south:Math.min(...xy.map(x=>x[1]!)),east:Math.max(...xy.map(x=>x[0]!)),north:Math.max(...xy.map(x=>x[1]!)),zoom:bounds.value.zoom};error.value=''})
async function poll(){if(!job.value||!running.value)return;try{job.value=await $fetch(`/api/map/cache-update/${job.value.id}`);if(running.value)timer=setTimeout(poll,1300);else emit('updated')}catch(e){error.value=errorMessage(e)}}
async function start(){if(busy.value||running.value)return;busy.value=true;error.value='';try{job.value=await $fetch('/api/map/cache-update',{method:'POST',body:{layerId:props.layer.id,...bounds.value,minZoom:Number(min.value),maxZoom:Number(max.value),replace:replace.value},retry:0});void poll()}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
async function cancel(){if(!job.value)return;try{await $fetch(`/api/map/cache-update/${job.value.id}/cancel`,{method:'POST'});void poll()}catch(e){error.value=errorMessage(e)}}
onMounted(()=>{if(running.value)void poll()});onBeforeUnmount(()=>clearTimeout(timer))
</script>
<template><div class="space-y-3 border-t border-default pt-4"><h3 class="font-medium">更新离线缓存</h3><p class="text-sm text-muted">默认使用刚才地图显示的范围，也可以重新圈画。更新时保留已有缓存，成功下载后替换对应图片。</p><LocationPicker v-model="shape" :disabled="!!running" /><p class="text-xs text-muted">范围：{{ bounds.west.toFixed(4) }}, {{ bounds.south.toFixed(4) }} 至 {{ bounds.east.toFixed(4) }}, {{ bounds.north.toFixed(4) }}</p><div class="field-grid"><UFormField label="最小级别"><UInput v-model.number="min" type="number" :min="layer.minZoom" :max="layer.maxZoom" class="w-full" :disabled="!!running" /></UFormField><UFormField label="最大级别"><UInput v-model.number="max" type="number" :min="layer.minZoom" :max="layer.maxZoom" class="w-full" :disabled="!!running" /></UFormField></div><UCheckbox v-model="replace" label="重新下载已有瓦片（取消勾选则只补缺失）" :disabled="!!running" /><p class="text-xs text-muted">每次最多 10000 张，先保存图层链接和密钥，再开始更新。</p><UAlert v-if="error" :description="error" color="error" /><div v-if="job" class="space-y-2"><UProgress :model-value="job.total?job.processed/job.total*100:0" /><p class="text-sm">{{ job.processed }} / {{ job.total }} · 成功 {{ job.downloaded }} · 失败 {{ job.failed }} · {{ ({running:'更新中',complete:'已完成',partial:'部分完成',cancelled:'已取消',failed:'更新失败'} as Record<string,string>)[job.state] }}</p><p v-if="job.error" class="text-sm text-warning">{{ job.error }}</p></div><div class="flex gap-2"><UButton label="开始更新缓存" icon="i-lucide-download" :disabled="!!running||!layer.urlTemplate" :loading="busy" @click="start" /><UButton v-if="running" label="取消更新" variant="outline" color="neutral" @click="cancel" /></div></div></template>
